head.script:
scwin.gVar = {
    "cInitClass" : null,
    "cInitStyle" : ""
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[body > M > setReadOnly]<br/>컴포넌트의 읽기 전용(readonly) 상태를 설정합니다.",
    "validation" : [
        "자식을 가지는 컴포넌트의 경우 컴포넌트의 읽기 전용(readonly) 상태는 자식 요소에게 동일하게 적용되어야 합니다.",
        "readOnly(필수) 파라미터로 true 설정 시 읽기 전용(readonly) 상태를 활성화 합니다.",
        "readOnly(필수) 파라미터로 false 설정 시 읽기 전용(readonly) 상태를 비활성화 합니다.",
        "입력 컴포넌트의 경우 읽기 전용(readonly)이 활성화되면 입력 및 편집이 차단되어야 합니다.",
        "읽기 전용(readonly)이 활성화되면 입력과 관계된 이벤트만 차단되고 나머지 이벤트는 발생하여야 합니다.",
        "읽기 전용(readonly)이 활성화되어도 컴포넌트의 포커스 획득이 가능하여야 합니다.",
        "입력 컴포넌트의 경우 읽기 전용(readonly)이 활성화되어도 컴포넌트의 텍스트 복사가 가능하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};




// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  body 는 동적 생성/삭제가 불가하므로 최초 렌더된 body 컴포넌트를 그대로 대상으로 사용하고,
//  "Target 재생성" 은 최초 렌더 시점의 class / style 상태로 되돌리는 것으로 대응한다.
scwin.comp_init = function () {
    let objBody = scwin.getBody();

    if (scwin.gVar["cInitClass"] === null) {
        // 최초 1회 : 초기 class / style 보관
        scwin.gVar["cInitClass"] = objBody.render.className;
        scwin.gVar["cInitStyle"] = objBody.render.getAttribute("style") || "";
    } else {
        // 재생성 : 초기 상태로 복원
        objBody.render.className = scwin.gVar["cInitClass"];
        objBody.render.setAttribute("style", scwin.gVar["cInitStyle"]);
    }

    // body 는 onclick/onfocus 등을 선언 이벤트로 제공하지 않으므로 bind() 로 등록한다
    scwin.getBody().bind("oncellclick", scwin.target1_oncellclick);
    scwin.getBody().bind("onchange", scwin.target1_onchange);
    scwin.getBody().bind("onclick", scwin.target1_onclick);
    scwin.getBody().bind("onfocus", scwin.target1_onfocus);
    scwin.getBody().bind("onkeydown", scwin.target1_onkeydown);
    scwin.getBody().bind("onviewchange", scwin.target1_onviewchange);
}



scwin.btn_setReadOnly_onclick = function (e) {
    scwin.getBody().setReadOnly(par_readOnly.getText());

    scwin.btn_getReadOnly_onclick();
};



scwin.btn_getReadOnly_onclick = function (e) {
    let rtn = '';

    rtn = scwin.getBody().getReadOnly();
    wf_body_bottom.getObj("scwin").setReturnValue("getReadOnly : " + rtn);    
};



// 테스트 샘플의 이벤트 처리
scwin.target1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclick 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   
}



scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeydown 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   
}



scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);
}



// 입력(값 변경) 관계 이벤트 — readOnly 활성화 시 사용자 조작에 의한 값 변경이 차단되어 발생하지 않아야 함
scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);
}



scwin.target1_oncellclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   
}



scwin.btn_focus_onclick = function (e) {
    scwin.getBody().focus();
};
// body 컴포넌트 조회
//  body 는 화면과 함께 렌더되는 컴포넌트로 $p.dynamicCreate / remove 대상이 아니고
//  공통 생성 함수($c.gcm.createBasicXxx)도 없어 공통 base(common_M) wrap 패턴을 쓸 수 없다.
//  <body id="target1"> 로 선언해도 body 는 root 요소라 scope 전역(target1)으로 등록되지 않으며
//  $p.getComponentById("target1") 도 scope 접두어가 적용되지 않아 undefined 를 반환하므로,
//  정적 선언된 자식(grp_main)의 parentControl 로 조회한다.
scwin.getBody = function () {
    return grp_main.parentControl;
}


// (검증) 자식 요소 readOnly 전파 확인
//  body 는 입력 컴포넌트가 아니므로 "입력·편집 차단 / 포커스 / 복사" 항목은 자식 입력 컴포넌트로 확인한다.
scwin.btn_checkChild_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let objBody = scwin.getBody();
    let attr = objBody.render.getAttribute("readonly");

    bottom.setReturnValue("body getReadOnly : " + objBody.getReadOnly()
        + " | body readonly 속성 : " + (attr === null ? "(없음)" : attr));

    let arr = [["input", child_input], ["textarea", child_textarea], ["select", child_select], ["calendar", child_calendar]];
    let parts = [];
    for (let i = 0; i < arr.length; i++) {
        let comp = arr[i][1];
        parts.push(arr[i][0] + "=" + (typeof comp.getReadOnly === "function" ? comp.getReadOnly() : "(메소드 없음)"));
    }
    bottom.setReturnValue("자식 getReadOnly : " + parts.join(", "));
}



// (검증) 입력 관련 이벤트만 차단되는지 : oninput 미발생 / onclick 발생 대비
scwin.child_input_oninput = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("자식 input oninput 발생 -> value : " + child_input.getValue());
}

scwin.child_input_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("자식 input onclick 발생");
}
